/// <summary>
///
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[DataEventHandler(tableStr(TAMRebateTrans), DataEventType::Updating)]
public static void TAMRebateTrans_onUpdating(Common sender, DataEventArgs e)
{
    TAMRebateTrans rebateTrans = sender as TAMRebateTrans;

    TAMRebateDeal   rebateDeal;
    TAMRebateDateTrans  rebateDateTrans;
    TAMRebateTable      rebateTable;
    METTierRateTrans    tierRateTrans;
    METTierRebateTrans  tierRebateTrans;

    select firstonly rebateTable
        where rebateTable.RebateId == rebateTrans.RebateId;

    select firstonly rebateDeal
        where rebateDeal.RecId == rebateTable.RebateDeal;

    if (rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    {
        select firstonly tierRateTrans
        where tierRateTrans.RebateId == rebateTrans.RebateId
        && tierRateTrans.FromDate <= rebateTrans.RebateRefDate
        && tierRateTrans.ToDate >= rebateTrans.RebateRefDate
        && (tierRateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate ||
           tierRateTrans.RebateTransactionType == TAMRebateTransactionType::Provision);

        if (tierRateTrans.RecId)
        {
            rebateTrans.RebateAmount = (rebateTrans.RebateRefAmount * tierRateTrans.EligibleRebate)/100;
            rebateTrans.PostingAmount = rebateTrans.RebateAmount;
        }
    }
}
